"""Original practice banks. Each content record has explicit mode/route/topic scope."""
import json,math,csv,pathlib,collections
R=pathlib.Path(__file__).resolve().parent.parent
U={s['id']:s for s in json.loads((R/'unit3/bank.json').read_text())['subjects']}
E={s['id']:s for s in json.loads((R/'content-bank.json').read_text())['subjects']}
B=json.loads((R/'questions/baseline-bank.json').read_text()); Q=B['questions']
def add(sid,key,prompt,answer,points,ut=None,et=None,stimulus='',table=None,level='medium',kind='model',route=None,working=None,note='',sources=()):
 scopes={};uid=route or sid
 if ut is not None:scopes['unit3']={'route':uid,'topics':[U[uid]['topics'][i] for i in ut]}
 if et is not None:scopes['ea']={'route':sid,'topics':[E[sid]['topics'][i]['title'] for i in et]}
 assert scopes
 q=dict(id=f'{sid}-expanded-{key}',template=key,subject=sid,title=prompt.split('\n')[0][:100],question=prompt,answer=answer if isinstance(answer,list) else [answer],scopes=scopes,points=[{'text':t,'marks':m} for t,m in points],marks=sum(m for t,m in points),difficulty=level,kind=kind,stimulus=stimulus,table=table,pitfall='Answer the command word and use the supplied evidence. Check each marking point before ticking it.',sources=[{'label':'QCAA syllabus: scope reference','url':(U[uid] if ut is not None else E[sid])['syllabus']}]+[{'label':'Concept reference','url':x} for x in sources])
 if working:q.update(working=[{'heading':h,'lines':ls} for h,ls in working],answerLayout='steps')
 if note:q['practiceType']=note
 Q.append(q);return q

def items(sid,rows,mode,**kw):
 for n,(topic,prompt,ans) in enumerate(rows):
  add(sid,f'{mode}-concept-{n}',prompt,ans,[('Accurate relevant concept or finding',1),('Explanation or application that directly answers the question',1)],**({'ut':[topic]} if mode=='unit3' else {'et':[topic]}),**kw)

# Definitions/application questions are individually authored, not random topic substitutions.
legal_u=[
(0,'Define the rule of law.','The rule of law requires public power to be exercised according to law. Everyone, including government officials, is subject to the law; decisions should follow lawful procedures rather than arbitrary personal power.'),
(0,'Explain how public reasons for an executive decision can improve government accountability.','Reasons make the legal and factual basis of the decision visible. Affected people, parliament or a review body can examine whether the power was exercised lawfully and challenge errors.'),
(1,'Explain how an election supports representative government in Australia.','Voters choose members of parliament to represent them. Elections provide a recurring opportunity to retain or replace those representatives based on their decisions and performance.'),
(1,'Explain why a minister answering questions in parliament is an example of responsible government.','The executive is accountable to parliament. Parliamentary questioning requires ministers to explain decisions and exposes their conduct to scrutiny by elected representatives.'),
(2,'Distinguish the roles of the legislature and the judiciary in Australia.','The legislature makes statute law. The judiciary decides disputes and interprets and applies law independently; it does not simply act on parliamentary directions about the outcome of individual cases.'),
(2,'Explain why judicial independence supports the rule of law.','Independent courts can determine disputes according to law without improper direction from the executive or parties. This permits judicial scrutiny of government conduct and fair adjudication.'),
(2,'Explain why Australia does not have a complete separation between the legislature and executive.','Ministers are drawn from parliament in the Westminster system. The executive and legislature therefore overlap, while judicial power is institutionally separated at the Commonwealth level.'),
(3,'Distinguish concurrent powers from residual powers in Australian federalism.','Concurrent powers may be exercised by both Commonwealth and state parliaments. Residual powers remain with the states because they have not been conferred on the Commonwealth.'),
(3,'A valid Commonwealth law and a valid state law directly conflict. Identify which prevails and explain the effect on the state law.','The Commonwealth law prevails to the extent of the inconsistency. The state law is inoperative to that extent; it is inaccurate to say the entire state Act must always disappear.'),
(4,'A constitutional referendum receives 49% national support and a majority in five states. Determine the result.','It fails. The national majority requirement is not met even though a majority in at least four states has been achieved.'),
(4,'A constitutional referendum receives 53% national support and a majority in four states. Determine whether the double-majority voting requirements are met.','Yes. More than half of voters nationally and a majority in at least four of the six states support the proposal. This answer addresses the voting thresholds in the stated scenario.'),
(4,'Explain why territory votes can affect the outcome of a constitutional referendum.','Territory votes count towards the national majority. They do not count as states when determining the separate majority-of-states requirement.'),
(5,'Distinguish a bill from an Act.','A bill is a proposal for legislation. It becomes an Act after passage through the required parliamentary process and royal assent; commencement may occur at a different time.'),
(5,'Explain one function of a parliamentary committee scrutinising a bill.','A committee can examine provisions, receive submissions and report on effects or problems. Its findings inform parliamentary consideration; it does not itself enact the bill.'),
(5,'Explain the purpose of a second-reading debate.','Members debate the principles and policy of a bill. This allows scrutiny of why the law is proposed and whether parliament should support its general objectives.'),
(6,'Explain what it means to describe Queensland’s parliament as unicameral.','Queensland has one legislative chamber, the Legislative Assembly. There is no state upper house to provide a second chamber of review.'),
(6,'Explain one reason parliamentary committees are important in Queensland’s unicameral system.','With no upper house, committees provide an important avenue for detailed scrutiny, evidence and public submissions. They help expose problems but do not reproduce every safeguard of a second chamber.'),
(7,'Explain how constitutional interpretation by the High Court can affect the division of powers.','The Court determines the meaning and limits of constitutional powers in disputes. Its interpretation can clarify whether Commonwealth or state action falls within constitutional authority.'),
(7,'Distinguish changing the Constitution’s text from interpreting it.','A referendum can alter constitutional text through the constitutional amendment process. A court interprets existing text in resolving disputes; interpretation does not itself replace the text.'),
(8,'Explain when a precedent is binding on a lower court.','A lower court generally follows the relevant legal principle of a higher court in the same hierarchy when materially similar facts and the same legal issue arise.'),
(8,'Distinguish ratio decidendi from obiter dicta.','The ratio is the legal reasoning necessary to the decision and can create binding precedent. Obiter consists of observations not necessary to resolve the case and may be persuasive.'),
(8,'Explain why a court may need to interpret a statutory word.','A word may be ambiguous or its application to new circumstances disputed. The court considers the text in context and the purpose of the legislation to determine its legal meaning.'),
(9,'Explain one potential benefit of a specialist tribunal for resolving disputes.','Specialist expertise and less formal procedures can make decisions more accessible or efficient for suitable disputes. The benefit depends on jurisdiction, powers, fees and review options.'),
(10,'A fictional proposal requires agencies to publish decision times. Identify one accountability benefit and one limitation.','Publication lets the public and parliament compare performance and identify delays. Times alone do not establish whether decisions are lawful or fair, so reasons and review information would also matter.'),
(10,'A fictional review service is independent but can only accept online applications. Explain a fairness concern and recommend one improvement.','People without internet access or digital skills may be unable to obtain review. Offer telephone or in-person assistance while retaining independent decision-making, improving practical accessibility.')]
items('legal',legal_u,'unit3',sources=['https://peo.gov.au/understand-our-parliament/how-parliament-works/system-of-government','https://www.legislation.gov.au/C2004Q00685/latest/text'],note='Original short-response practice. Legal explanations are summaries, not quotations.')
legal_e=[
(0,'Define a treaty in international law.','A treaty is an international agreement governed by international law. It creates obligations for states that consent to be bound, subject to its terms and applicable reservations.'),
(1,'Distinguish a human right from a legal remedy.','A human right is a fundamental entitlement or standard concerning human dignity and freedom. A remedy is a process or response for addressing a breach; recognising a right does not itself guarantee an effective domestic remedy.'),
(2,'Explain why the UDHR and ICCPR have different legal forms.','The UDHR is a declaration of standards, whereas the ICCPR is a treaty binding its states parties internationally. Neither label alone establishes whether a particular claim is enforceable in an Australian court.'),
(2,'Distinguish one civil or political right from one economic, social or cultural right.','Freedom of expression is a civil or political right; education is an economic, social or cultural right. Both concern human dignity, but protect different aspects of participation and wellbeing.'),
(3,'Explain the central idea of non-refoulement in refugee protection.','It restricts returning a refugee to a territory where their life or freedom would be threatened for a Convention reason. The precise legal test and any exceptions depend on the applicable instrument and circumstances.'),
(3,'Distinguish an asylum seeker from a recognised refugee.','An asylum seeker is seeking international protection and awaits determination of their claim. A recognised refugee has been found to satisfy the refugee definition; seeking asylum does not itself establish that determination.'),
(4,'Identify the human rights issue targeted by ICERD and explain its international role.','ICERD concerns racial discrimination. It requires states parties to take measures to eliminate such discrimination and promote equality, with international monitoring; domestic remedies depend on domestic law.'),
(5,'Explain the purpose of CEDAW.','CEDAW addresses discrimination against women and requires states parties to pursue its elimination. It provides international standards and monitoring rather than automatically replacing Australian legislation.'),
(6,'Explain how accessibility relates to the rights of people with disability.','Accessible facilities, information and services enable participation on an equal basis. Removing barriers can make rights usable in practice instead of merely formally recognised.'),
(7,'Explain why torture raises an international human rights issue even when a state calls it a domestic security measure.','International human rights obligations constrain state conduct. Labelling torture a security measure does not remove the prohibition or make national sovereignty an unlimited defence.'),
(8,'Explain why children may require specific human rights protections.','Children may depend on adults and have limited power to protect their own interests. Child-specific standards address their development, safety and participation as rights holders.'),
(9,'Distinguish signature from ratification of a treaty.','Signature commonly indicates support and may carry obligations concerning the treaty’s object and purpose, but does not always make a state a party. Ratification is a formal international act of consent to be bound where that process applies.'),
(9,'Explain why ratification does not automatically create an Australian cause of action for every treaty right.','International obligations and domestic legal enforceability are distinct. Domestic legislation may implement treaty commitments; ratification alone does not incorporate all provisions into Australian law.'),
(10,'Explain one tension between sovereignty and international human rights monitoring.','States exercise authority within their territory, while international monitoring scrutinises whether they meet accepted obligations. A state may resist external criticism even where it has consented to treaty standards.'),
(11,'Distinguish the roles of UNHCR and an Australian court in a refugee matter.','UNHCR has an international protection and assistance mandate. An Australian court determines matters within its jurisdiction under applicable law, such as judicial review; UNHCR does not replace that court.'),
(12,'Explain one limitation of treating Magna Carta as a modern universal bill of rights.','Its historical protections were developed in a particular medieval setting and were not equal universal rights for everyone. It influenced later limits on arbitrary power, but should not be described as a complete modern rights code.'),
(13,'Distinguish direct from indirect discrimination.','Direct discrimination involves less favourable treatment on a protected basis under the applicable legal test. Indirect discrimination can arise from an apparently neutral requirement that disadvantages a protected group and fails the relevant justification test.'),
(14,'Explain why Australia’s Constitution is not a comprehensive bill of rights.','It contains some express protections and limits, together with judicially recognised implications, but does not comprehensively enumerate all internationally recognised rights. Many protections arise from legislation and common law.'),
(15,'Explain why the implied freedom of political communication should not be described as a general personal right to say anything.','It is a constitutional restriction on governmental power that protects political communication needed for representative and responsible government. Its operation is not an unlimited individual licence covering all speech.'),
(16,'Explain how access to legal assistance can affect equality before the law.','Formal equality does not ensure people can understand procedures or present a case. Assistance can reduce practical barriers and improve meaningful participation in resolving disputes.'),
(17,'Explain why conciliation and adjudication are different complaint processes.','Conciliation helps parties seek an agreed resolution. Adjudication involves an authorised decision-maker determining the dispute; the availability and legal effect of each depend on the governing law.'),
(18,'Explain why a complaint to the Australian Human Rights Commission does not automatically produce a binding court order.','The Commission investigates and conciliates relevant complaints within its powers. It is not a court; unresolved eligible matters may require a separate court process to obtain judicial remedies.'),
(19,'Distinguish the roles of a law reform commission and a parliament.','A law reform commission investigates issues and recommends reforms. Parliament decides whether to enact legislation; recommendations do not themselves change the law.'),
(20,'Explain one benefit and one limitation of media reporting about a human rights complaint.','Reporting can raise awareness and place pressure on authorities to respond. Incomplete or sensational coverage can distort evidence or damage privacy, so publicity is not a substitute for a fair legal process.'),
(22,'A fictional complaints form is abandoned by 40 of 100 users. Recommend one access reform and identify evidence needed to evaluate it.','Provide plain-language assistance or an accessible alternative submission process. Compare completion rates and user feedback before and after implementation, while checking that complaints are understood and accurately recorded.')]
