 ('headwind',f'In a one-dimensional model, true airspeed is {speed} km/h and a direct headwind is {20+5*k} km/h. Calculate ground speed and time for a {speed-20-5*k} km leg.',f'Ground speed = {speed-20-5*k} km/h; time = 1 hour.',[('Subtracts headwind',1),('Correct ground speed',1),('Correct duration',1)],None,[2,4],[('Ground speed',[f'{speed} − {20+5*k} = {speed-20-5*k} km/h']),('Time',[f't = {speed-20-5*k}/{speed-20-5*k} = 1 h'])]),
 ('maintenance',f'A classroom maintenance schedule requires inspection every {50+10*k} operating hours. An aircraft has accumulated {43+8*k} hours since inspection and is proposed for a {10+k}-hour operation. Determine whether the model inspection limit would be exceeded.',f'Proposed total = {53+9*k} h; exceeds the stipulated limit by {3-k} h.' if k<3 else (f'Proposed total = {53+9*k} h; equals the limit.' if k==3 else f'Proposed total = {53+9*k} h; remains 1 h below the limit.'),[('Adds proposed operation time',1),('Correct comparison with stipulated limit',1)],None,[3],[('Total',[f'{43+8*k} + {10+k} = {53+9*k} h']),('Compare',[f'Limit = {50+10*k} h',f'Total minus limit = {3-k} h','Apply the stated classroom limit; actual maintenance requirements depend on approved schedules.'])]),
