 ('realgrowth',f'Nominal GDP grows by {(nominal-1)*100:.1f}% and the GDP price index by {(price-1)*100:.1f}%. Calculate real GDP growth using the exact growth-factor method.',f'{(nominal/price-1)*100:.2f}%.',[('Divides nominal growth factor by price growth factor',1),('Subtracts one and converts to percentage',1),('Correct result',1)],5,[('Growth factor',[f'{nominal:.3f}/{price:.3f} = {nominal/price:.6f}']),('Percentage',[f'({nominal/price:.6f} − 1) × 100 ≈ {(nominal/price-1)*100:.2f}%'])]),
