for base in ['chinese','french','german']:
 sid=base+'_ext'
 for i,(text,meaning,activity,tech,view,response) in enumerate(LANG[base]):
  tasks=[('Analyse the qualified viewpoint in the text. Respond in your course language.',f'The viewpoint balances benefits and constraints: {view}. Explain how {response} responds to the concern; use precise phrases from the text.'),
   ('Explain how contrast organises the text’s argument. Respond in your course language.',f'The positive account of {activity} is qualified by a concern, followed by {response}. Analyse this movement rather than merely translating each sentence.'),
   ('Develop a counterargument to one assumption in the text. Respond in your course language.',f'Identify an assumption about access, participation or technology, then offer a relevant challenge and consider the text’s proposed response. The original position is: {view}. A counterargument must engage with that position accurately.'),
   ('Connect the text’s local example to a broader issue of participation. Respond in your course language.',f'Use {activity}, {tech} and {response} as specific evidence, then explain a broader tension between opportunity and access or responsible use. Avoid claiming that one group represents all society.'),
   ('Construct a concise analytical argument about how the text presents individual and group needs. Respond in your course language.',f'One defensible line of argument is that participation is valuable but needs practical conditions: {view}. Support this with the response of {response}; show how the structure moves from benefit to qualification and action.')]
  for j,(prompt,ans) in enumerate(tasks):
   q=add(sid,f'extension-{i}-{j}',prompt,[ans,'Meaning check: '+meaning,'Course-language evidence and expression reference:\n'+text],[('Accurate nuanced interpretation',2),('Analysis using precise textual evidence',2),('Connected course-language argument',2)],ut=[0,1,2],route=sid+'-ia1',et=[0,1,2,3,4,5],stimulus='Original written stimulus for language-analysis practice.\n'+text,note='Conceptual answer guide with course-language evidence. Not a full target-language essay or listening stimulus. Relate broader arguments to your teacher-confirmed focus.')
   q['scopes']['unit3']['route']=sid+'-ia1'
   # Separate route record: the same analysis can be prepared aloud for IA2.
   import copy
   other=copy.deepcopy(q);other['id']+='-oral';other['scopes']={'unit3':{'route':sid+'-ia2','topics':U[sid+'-ia2']['topics'][:]}};other['question']='Prepare and deliver an oral response in your course language.\n'+prompt.replace('Respond in your course language.','')
   other['practiceType']='Oral preparation practice with conceptual guidance. No listening stimulus, recording or automatic speech assessment is supplied.';Q.append(other)
