counts=[]
for mode,routes in [('unit3',U),('ea',E)]:
 for sid,s in routes.items():
  pool=[q for q in Q if q.get('scopes',{}).get(mode,{}).get('route')==sid]
  titles=s['topics'] if mode=='unit3' else [t['title'] for t in s['topics']]
  seen=collections.Counter(t for q in pool for t in q['scopes'][mode]['topics'])
  missing=[(i,t) for i,t in enumerate(titles) if not seen[t]]
  if len(pool)<25 or missing:print(mode,sid,len(pool),'MISSING',missing)
  counts.append((mode,sid,len(pool),len(titles),len(titles)-len(missing)))
assert len({q['id'] for q in Q}) == len(Q), 'Duplicate question id'
for mode,sid,n,total,covered in counts:
 assert n>=25 and total==covered, (mode,sid,n,total,covered)
B.update(version='2026-10-15.3',questions=Q,notice='Original practice questions and answer guides. Marks are indicative, not official QCAA marking schemes. Some numerical questions are parameter variations. Topic coverage refers to the planner’s mapped topics, not every possible syllabus question. Text-dependent and source-skills exercises are labelled; use your class materials for prescribed knowledge.')
(R/'question-bank.json').write_text(json.dumps(B,ensure_ascii=False,indent=2)+'\n')
(R/'question-data.js').write_text('window.PRACTICE_QUESTIONS = '+json.dumps(B,ensure_ascii=False).replace('</','<\\/')+';\n')
with (R/'questions/coverage-audit.csv').open('w') as f:
 w=csv.writer(f);w.writerow(['Mode','Route','Questions','Mapped topics','Topics with questions']);w.writerows(counts)
print('TOTAL',len(Q),'records')
